import metaFile from "@/public/data/avalanche-meta.json";

/** Region names and official services, generated by scripts/build-regions.ts. */
export interface RegionMeta {
  regions: Record<string, { n: [string, string]; o: string | null }>;
  services: Record<string, { name: string; url: string }[]>;
}

export const regionMeta = metaFile as unknown as RegionMeta;

export function metaName(
  meta: RegionMeta,
  id: string,
  locale: "en" | "pl",
): string | undefined {
  return meta.regions[id]?.n[locale === "pl" ? 1 : 0];
}

export function servicesFor(
  meta: RegionMeta,
  id: string,
): { name: string; url: string }[] {
  const outline = meta.regions[id]?.o;
  return (outline && meta.services[outline]) || [];
}

/**
 * Display name of a region. English: the provider's own English name, then EAWS (whose "English"
 * names are often untranslated local names). Polish: EAWS's Polish name, then the provider's.
 */
export function regionLabel(
  meta: RegionMeta | null,
  id: string,
  locale: "en" | "pl",
  providerName?: string,
): string {
  const fromMeta = meta ? metaName(meta, id, locale) : undefined;
  return (
    (locale === "pl"
      ? (fromMeta ?? providerName)
      : (providerName ?? fromMeta)) ?? id
  );
}
